import { stringify } from '../vendor/yaml/index.mjs';
import { YamlTimestamp, isBinary, padNumber } from './types.mjs';

export function scalarToLines(value) {
  if (value instanceof YamlTimestamp) {
    return [formatTimestamp(value)];
  }

  if (typeof value === 'string') {
    if (containsCharacter(value, '\n')) {
      return splitLines(trimTrailingNewline(stringify(value, {
        defaultStringType: 'QUOTE_SINGLE',
        version: '1.1'
      })));
    }

    return splitLines(trimTrailingNewline(stringify(value, {
      singleQuote: true,
      version: '1.1'
    })));
  }

  if (isBinary(value)) {
    return splitLines(trimTrailingNewline(stringify(Buffer.from(value), {
      version: '1.1'
    })));
  }

  return splitLines(trimTrailingNewline(stringify(value, {
    singleQuote: true,
    version: '1.1'
  })));
}

export function isPlainRootScalar(lines) {
  if (lines.length !== 1) {
    return false;
  }

  if (lines[0].length === 0) {
    return false;
  }

  const first = lines[0][0];
  return first !== '\'' && first !== '"' && first !== '!' && first !== '|' && first !== '>';
}

function formatTimestamp(value) {
  let text = padNumber(value.year, 4) + '-' + padNumber(value.month, 2) + '-' + padNumber(value.day, 2);

  if (!value.hasTime) {
    return text;
  }

  text += ' ' + padNumber(value.hour, 2) + ':' + padNumber(value.minute, 2) + ':' + padNumber(value.second, 2);

  if (value.microsecond !== 0) {
    text += '.' + padNumber(value.microsecond, 6);
  }

  if (value.hasZone) {
    const offset = value.offsetMinutes;
    const sign = offset < 0 ? '-' : '+';
    const absolute = offset < 0 ? -offset : offset;
    const hours = Math.floor(absolute / 60);
    const minutes = absolute % 60;
    text += sign + padNumber(hours, 2) + ':' + padNumber(minutes, 2);
  }

  return text;
}

function trimTrailingNewline(text) {
  if (text.endsWith('\n')) {
    return text.slice(0, -1);
  }
  return text;
}

function splitLines(text) {
  return text.split('\n');
}

function containsCharacter(text, character) {
  for (let i = 0; i < text.length; i += 1) {
    if (text[i] === character) {
      return true;
    }
  }
  return false;
}

