export function parseCommandLine(argv) {
  const program = basename(argv[1] || 'test16.mjs');
  const argumentsList = argv.slice(2);
  const extras = [];
  let value;

  for (let index = 0; index < argumentsList.length; index += 1) {
    const token = argumentsList[index];

    if (token === '-h' || token === '--help') {
      return {
        help: true,
        program
      };
    }

    if (token === '--') {
      for (let extraIndex = index; extraIndex < argumentsList.length; extraIndex += 1) {
        extras.push(argumentsList[extraIndex]);
      }
      break;
    }

    if (token === '--a') {
      const next = argumentsList[index + 1];
      if (typeof next === 'undefined' || next === '--' || startsLikeOption(next)) {
        throw usageError(program, 'argument --a: expected one argument');
