import { parseCommandLine, printHelp, printUsageError } from './lib/cli.mjs';
import { dumpYaml } from './lib/dump-yaml.mjs';
import { loadYaml } from './lib/load-yaml.mjs';

export function main(argv = process.argv) {
  const parsed = parseCommandLine(argv);

  if (parsed.help) {
    printHelp(parsed.program);
    return 0;
  }

  const value = loadYaml(parsed.options.a);
  const output = dumpYaml(value);
  process.stdout.write(output + '\n');
  return 0;
}

try {
  process.exitCode = main(process.argv);
} catch (error) {
  if (error && error.isUsageError) {
    printUsageError(error);
    process.exitCode = 2;
  } else {
    throw error;
  }
}

